const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Houston geometry
  const houston = ee.Geometry.Point([-95.3698, 29.7604]).buffer(20000); // 20km radius around Houston

  // 2. Try to get VIIRS monthly nighttime lights data
  const viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG');

  // April 2024 average
  const april2024 = viirs
    .filterDate('2024-04-01', '2024-05-01')
    .filterBounds(houston)
    .select('avg_rad');

  // May 2024 (as proxy for May 18, 2024)
  const may2024 = viirs
    .filterDate('2024-05-01', '2024-06-01')
    .filterBounds(houston)
    .select('avg_rad');

  const aprilSize = april2024.size().getInfo();
  const maySize = may2024.size().getInfo();

  console.log(`April 2024 images: ${aprilSize}`);
  console.log(`May 2024 images: ${maySize}`);

  // 3. Check if data exists
  if (aprilSize === 0 || maySize === 0) {
    console.log("No data available for comparison period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Calculate mean nighttime light intensity
  const aprilImg = april2024.mean();
  const mayImg = may2024.mean();

  // 5. Reduce to get statistics
  const aprilStats = aprilImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const mayStats = mayImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const aprilMean = aprilStats.avg_rad_mean;
  const aprilCount = aprilStats.avg_rad_count;
  const mayMean = mayStats.avg_rad_mean;
  const mayCount = mayStats.avg_rad_count;

  console.log(`April 2024 mean intensity: ${aprilMean}, pixels: ${aprilCount}`);
  console.log(`May 2024 mean intensity: ${mayMean}, pixels: ${mayCount}`);

  // 6. Validation
  if (aprilCount === 0 || mayCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (aprilMean === null || mayMean === null || 
      isNaN(aprilMean) || isNaN(mayMean) ||
      aprilMean < 0 || mayMean < 0) {
    console.log("Invalid calculation results.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare and answer
  const decreased = mayMean < aprilMean;
  const percentChange = ((mayMean - aprilMean) / aprilMean * 100).toFixed(2);

  console.log(`Change: ${percentChange}% (May vs April)`);

  if (decreased) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
